test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Issue #1: the ball must bounce off bricks -----------------------------
// Each face case below was written red (failing) first, then made green.

// A single live brick, positioned like a grid brick.
function oneBrick(x = 84, y = 48) {
  return [{ x, y, w: 72, h: 20, row: 0, alive: true, points: 50 }];
}

test('brickHit: head-on hit from below flips vy (bottom face)', () => {
  const ball = { x: 120, y: 73, r: 7, vx: 0, vy: -260 }; // rising into the brick
  const bricks = oneBrick();
  const hit = brickHit(ball, bricks, 120, 76); // swept from below
  assert.equal(hit.length, 1);
  assert.equal(ball.vy, 260, 'vy should flip');
  assert.equal(ball.vx, 0, 'other component untouched');
  assert.equal(ball.y, 68 + 7, 'ball pushed out below the brick');
  assert.equal(bricks[0].alive, false);
  assert.equal(collides(ball, bricks[0]), false, 'no sticky overlap after push-out');
});

test('brickHit: head-on hit from above flips vy (top face)', () => {
  const ball = { x: 120, y: 43, r: 7, vx: 0, vy: 260 }; // falling into the brick
  const bricks = oneBrick();
  const hit = brickHit(ball, bricks, 120, 40);
  assert.equal(hit.length, 1);
  assert.equal(ball.vy, -260);
  assert.equal(ball.vx, 0, 'other component untouched');
  assert.equal(ball.y, 48 - 7, 'ball pushed out above the brick');
  assert.equal(bricks[0].alive, false);
});

test('brickHit: side hit flips vx and leaves vy untouched', () => {
  const ball = { x: 88, y: 60, r: 7, vx: 260, vy: 0 }; // sliding into the left face
  const bricks = oneBrick();
  const hit = brickHit(ball, bricks, 77, 60); // swept from the left, tangent start
  assert.equal(hit.length, 1);
  assert.equal(ball.vx, -260);
  assert.equal(ball.vy, 0, 'other component untouched');
  assert.equal(ball.x, 84 - 7, 'ball pushed out left of the brick');
  assert.equal(bricks[0].alive, false);
});

test('brickHit: exact corner hit flips both components', () => {
  const ball = { x: 82, y: 46, r: 7, vx: 260, vy: 260 }; // diagonal into the corner
  const bricks = oneBrick();
  const hit = brickHit(ball, bricks, 77, 41);
  assert.equal(hit.length, 1);
  assert.equal(ball.vx, -260);
  assert.equal(ball.vy, -260);
  assert.equal(ball.x, 84 - 7, 'ball pushed out left');
  assert.equal(ball.y, 48 - 7, 'ball pushed out above');
  assert.equal(bricks[0].alive, false);
});

test('brickHit: seam between two bricks — both break, bounce applied exactly once', () => {
  const ball = { x: 160, y: 73, r: 7, vx: 0, vy: -260 }; // straddling the seam
  const bricks = [
    { x: 84, y: 48, w: 72, h: 20, row: 0, alive: true, points: 50 },
    { x: 164, y: 48, w: 72, h: 20, row: 0, alive: true, points: 50 },
  ];
  const hit = brickHit(ball, bricks, 160, 76);
  assert.equal(hit.length, 2, 'both seam bricks break');
  assert.ok(bricks.every((b) => !b.alive));
  assert.equal(ball.vy, 260, 'vy flipped exactly once (a double flip would cancel out)');
  assert.equal(ball.y, 48 + 20 + 7, 'ball pushed out below both bricks');
});

test('brickHit: ball grazing past without crossing the brick does not bounce', () => {
  const ball = { x: 300, y: 60, r: 7, vx: 260, vy: 0 };
  const bricks = oneBrick();
  const hit = brickHit(ball, bricks, 290, 60);
  assert.equal(hit.length, 0);
  assert.equal(ball.vx, 260, 'velocity untouched');
  assert.equal(bricks[0].alive, true);
});

test('step: head-on brick hit from below — bounce, push-out, brick broken, scored', () => {
  const state = createState(1);
  const brick = state.bricks[BRICK_COLS * (BRICK_ROWS - 1)]; // bottom row, leftmost
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + BALL_R + 1;
  state.ball.vx = 0;
  state.ball.vy = -ballSpeed(1);
  const scoreBefore = state.score;
  step(state, 1 / 60);
  assert.equal(brick.alive, false);
  assert.equal(state.ball.vy, ballSpeed(1), 'vy flipped exactly once');
  assert.equal(state.ball.y, brick.y + brick.h + BALL_R, 'ball pushed out below');
  assert.ok(state.score > scoreBefore, 'brick was scored');
  assert.equal(state.combo, 1);
});

test('step: fast ball cannot tunnel through a row (swept detection)', () => {
  const state = createState(6); // ballSpeed(6) = 710 px/s
  const brick = state.bricks[0]; // top row, leftmost: y 48..68
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - BALL_R - 1;
  state.ball.vx = 0;
  state.ball.vy = ballSpeed(6);
  step(state, 1 / 20); // dt = 50 ms (capped): a 35.5 px jump, wider than the row
  assert.equal(brick.alive, false, 'brick crossed in one step still breaks');
  assert.ok(state.ball.vy < 0, 'ball bounced back up');
  assert.equal(state.ball.y, brick.y - BALL_R, 'ball pushed out above the brick');
  // The row below is only reached AFTER the bounce would have happened: it survives.
  assert.equal(state.bricks[BRICK_COLS].alive, true);
});

